def gate(results, baseline, threshold, margin):
    reasons = []
    rate = sum(r['passed'] for r in results) / len(results)
    if rate < threshold:
        reasons.append('overall below threshold')
    for r in results:
        if 'must_pass' in r['tags'] and not r['passed']:
            reasons.append('must_pass failed: ' + r['id'])
    for tag, base in baseline.items():
        tagged = [r for r in results if tag in r['tags']]
        if tagged:
            tag_rate = sum(r['passed'] for r in tagged) / len(tagged)
            if tag_rate < base - margin - 1e-9:
                reasons.append('regression: ' + tag)
    return sorted(reasons)
